"""Guards for the development-only credential defaults in docker-compose.yml.

The development compose stack must keep working with no configuration, but
its credential defaults have to be visibly development-only: interpolated
from the environment (so a ``.env`` file overrides them) and recognised by
the backend's startup warnings when the placeholder is actually used.
"""

from __future__ import annotations

import logging
from collections.abc import Iterator
from pathlib import Path
from typing import Dict

import pytest
import yaml

from preloop.config import (
    is_placeholder_jwt_secret,
    logger as config_logger,
    warn_default_database_credentials,
)

REPO_ROOT = Path(__file__).resolve().parents[2]
COMPOSE_FILE = REPO_ROOT / "docker-compose.yml"

SECRET_KEY_DEFAULT = "${SECRET_KEY:-development_secret_key_do_not_use_in_production}"
POSTGRES_PASSWORD_DEFAULT = "${POSTGRES_PASSWORD:-postgres}"
DATABASE_URL_DEFAULT = (
    "postgresql+psycopg://postgres:${POSTGRES_PASSWORD:-postgres}@postgres/preloop"
)


class _CapturingHandler(logging.Handler):
    """Collect records from preloop.config (propagate=False after setup)."""

    def __init__(self) -> None:
        super().__init__(level=logging.DEBUG)
        self.messages: list[str] = []

    def emit(self, record: logging.LogRecord) -> None:
        self.messages.append(record.getMessage())


@pytest.fixture
def config_logs() -> Iterator[_CapturingHandler]:
    handler = _CapturingHandler()
    config_logger.addHandler(handler)
    try:
        yield handler
    finally:
        config_logger.removeHandler(handler)


def _compose_services() -> Dict[str, Dict]:
    return yaml.safe_load(COMPOSE_FILE.read_text())["services"]


def test_secret_key_defaults_are_env_interpolated() -> None:
    """Every SECRET_KEY is overridable and falls back to the dev placeholder."""
    services = _compose_services()
    holders = {
        name: spec["environment"]["SECRET_KEY"]
        for name, spec in services.items()
        if "SECRET_KEY" in (spec.get("environment") or {})
    }
    assert holders, "no compose service carries SECRET_KEY"
    for name, value in holders.items():
        assert value == SECRET_KEY_DEFAULT, name


def test_postgres_password_default_is_env_interpolated() -> None:
    """The postgres password is overridable and falls back to the dev default."""
    services = _compose_services()
    postgres_env = services["postgres"]["environment"]
    assert postgres_env["POSTGRES_PASSWORD"] == POSTGRES_PASSWORD_DEFAULT
    for name, spec in services.items():
        url = (spec.get("environment") or {}).get("DATABASE_URL")
        if url is not None:
            assert url == DATABASE_URL_DEFAULT, name


def test_postgres_port_binds_to_loopback_only() -> None:
    """A database with a default dev password must not listen on 0.0.0.0."""
    services = _compose_services()
    assert services["postgres"]["ports"] == ["127.0.0.1:5432:5432"]


def test_compose_secret_key_fallback_triggers_the_startup_warning() -> None:
    """The compose fallback is a known placeholder, so startup warns on it."""
    fallback = SECRET_KEY_DEFAULT.split(":-", 1)[1].rstrip("}")
    assert is_placeholder_jwt_secret(fallback) is True


def test_default_database_credentials_warn(
    config_logs: _CapturingHandler,
) -> None:
    """postgres:postgres credentials produce a startup warning, value-free."""
    warn_default_database_credentials(
        "postgresql+psycopg://postgres:postgres@postgres/preloop"
    )
    text = "\n".join(config_logs.messages)
    assert "development default" in text
    assert "postgres/preloop" not in text


@pytest.mark.parametrize(
    "url",
    [
        "postgresql+psycopg://postgres:s3cure-real-password@postgres/preloop",
        "postgresql+psycopg://app_user:postgres@postgres/preloop",
        "postgresql+psycopg://postgres@postgres/preloop",
        "not a url at all",
    ],
)
def test_non_default_database_credentials_stay_silent(
    url: str, config_logs: _CapturingHandler
) -> None:
    """Real credentials (and unparseable URLs) produce no warning."""
    warn_default_database_credentials(url)
    assert config_logs.messages == []

"""Inventory and exact handler matching for restricted HTTP policies."""

from collections.abc import Iterator, Mapping
from types import SimpleNamespace
from typing import Any

from starlette.routing import Match, Mount
from starlette.types import Scope

from preloop.schemas.ci_principal import CiAction


def effective_routes(app: Any) -> Iterator[Any]:
    """Include lazy FastAPI routers as well as ordinary Starlette routes."""
    for route in app.routes:
        contexts = getattr(route, "effective_route_contexts", None)
        if callable(contexts):
            yield from contexts()
        else:
            yield route


def route_description(route: Any) -> tuple[str, set[str], Any]:
    """Read the effective path/method/endpoint across FastAPI versions."""
    original = getattr(route, "original_route", route)
    concrete = getattr(route, "starlette_route", None) or original
    path = getattr(route, "path", "") or getattr(concrete, "path", "")
    methods = getattr(route, "methods", None) or getattr(concrete, "methods", None)
    if not methods:
        methods = {"MOUNT"} if hasattr(concrete, "routes") else {"WEBSOCKET"}
    endpoint = getattr(route, "endpoint", None) or getattr(original, "endpoint", None)
    return path, set(methods), endpoint


def restricted_route_inventory(app: Any, prefix: str = "") -> dict[str, str]:
    """Every operation has an explicit deny or supported action classification."""
    inventory: dict[str, str] = {}
    for route in effective_routes(app):
        path, methods, endpoint = route_description(route)
        action = getattr(endpoint, "_ci_action", None)
        policy = action.value if isinstance(action, CiAction) else "deny"
        for method in methods:
            name = f"{method} {prefix}{path}"
            if name in inventory:
                raise ValueError(f"Ambiguous restricted route policy: {name}")
            inventory[name] = policy
        original = getattr(route, "original_route", route)
        concrete = getattr(route, "starlette_route", None) or original
        children = None
        mounted = concrete
        seen: set[int] = set()
        while mounted is not None and id(mounted) not in seen:
            seen.add(id(mounted))
            children = getattr(mounted, "routes", None)
            if children:
                break
            mounted = getattr(mounted, "app", None)
        if children:
            nested = restricted_route_inventory(
                SimpleNamespace(routes=children), prefix=prefix + path
            )
            overlap = set(inventory) & set(nested)
            if overlap:
                raise ValueError(
                    f"Ambiguous mounted restricted policies: {sorted(overlap)}"
                )
            inventory.update(nested)
    return inventory


def matched_machine_handler(scope: Scope, action: CiAction) -> bool:
    """Only the router's first matching handler can opt into machine authority.

    Pattern overlap or a newly added alias must not send a machine context to
    an unrelated/public handler merely because its URL matches an allow rule.
    """
    app = scope.get("app")
    if app is None:
        return False
    for route in effective_routes(app):
        match, _ = route.matches(scope)
        if match == Match.FULL:
            _, _, endpoint = route_description(route)
            return getattr(endpoint, "_ci_action", None) == action
    return False


def validate_machine_policies(
    app: Any, policies: Mapping[tuple[str, str], CiAction]
) -> None:
    """Reject mounted allow rules until nested dispatch is explicitly supported."""
    if not policies:
        return
    seen: set[int] = set()
    while app is not None and id(app) not in seen:
        seen.add(id(app))
        if hasattr(app, "routes"):
            break
        app = getattr(app, "app", None)
    if app is None or not hasattr(app, "routes"):
        raise ValueError("Restricted CI policies require an inspectable router")
    for method, path in policies:
        scope: Scope = {
            "type": "http",
            "method": method,
            "path": path,
            "root_path": "",
        }
        for route in effective_routes(app):
            original = getattr(route, "original_route", route)
            concrete = getattr(route, "starlette_route", None) or original
            if isinstance(concrete, Mount):
                match, _ = concrete.matches(scope)
                if match == Match.FULL:
                    raise ValueError(
                        f"Mounted restricted CI operations are unsupported: "
                        f"{method} {path}"
                    )

import { expect } from '@open-wc/testing';
import type { ManagedAgentSummary } from '../types';
import { agentActions } from './agent-actions';
import { actionIds, intersectActions } from './registry';

function makeAgent(
  overrides: Partial<ManagedAgentSummary> = {}
): ManagedAgentSummary {
  return {
    id: 'agent-1',
    runtime_session_id: 'session-1',
    owner_user_id: null,
    owner_username: null,
    owner_email: null,
    display_name: 'Alpha runner',
    session_source_type: 'claude_code',
    session_source_id: 'workspace-1',
    session_reference: 'ref-1',
    enrolled_via: 'runtime_session_token',
    managed_mcp_servers: [],
    lifecycle_state: 'active',
    lifecycle_reason: null,
    lifecycle_updated_at: null,
    is_active_now: true,
    activity_status: 'active_now',
    last_seen_at: '2026-09-01T10:00:00Z',
    started_at: null,
    last_activity_at: null,
    ended_at: null,
    total_requests: 0,
    estimated_cost: 0,
    configured_model_alias: null,
    latest_model_alias: null,
    latest_provider_name: null,
    last_request_at: null,
    mcp_proxy_configured: true,
    model_gateway_configured: true,
    onboarding_state: 'fully_onboarded',
    ...overrides,
  } as ManagedAgentSummary;
}

/** Every handler a list row wires. */
const rowCtx = {
  onTalk: () => {},
  onRename: () => {},
  onEditTags: () => {},
  onChangeOwner: () => {},
  onLifecycle: () => {},
  onRemove: () => {},
};

describe('agentActions', () => {
  it('offers pause and decommission for a running agent', () => {
    expect(actionIds(agentActions(makeAgent(), rowCtx))).to.deep.equal([
      'rename',
      'edit-tags',
      'pause',
      'decommission',
      'remove',
    ]);
  });

  it('offers resume instead of pause for a suspended agent', () => {
    const ids = actionIds(
      agentActions(makeAgent({ lifecycle_state: 'suspended' }), rowCtx)
    );
    expect(ids).to.contain('resume');
    expect(ids).to.not.contain('pause');
    expect(ids).to.contain('decommission');
  });

  it('never offers decommission twice for a decommissioned agent', () => {
    const ids = actionIds(
      agentActions(makeAgent({ lifecycle_state: 'decommissioned' }), rowCtx)
    );
    expect(ids).to.deep.equal(['rename', 'edit-tags', 'resume', 'remove']);
  });

  it('adds Change owner only where an owner can be chosen', () => {
    expect(
      actionIds(agentActions(makeAgent(), { ...rowCtx, canChangeOwner: true }))
    ).to.contain('change-owner');
    expect(actionIds(agentActions(makeAgent(), rowCtx))).to.not.contain(
      'change-owner'
    );
  });

  it('leads with Talk for an agent with Agent Control, disabled while offline', () => {
    const connected = agentActions(
      makeAgent({
        control_state: 'plugin_connected',
        control_enabled: true,
        control_online: true,
        control_capabilities: ['send_text_prompt'],
      } as Partial<ManagedAgentSummary>),
      rowCtx
    );
    expect(connected[0].id).to.equal('talk');
    expect(connected[0].disabled).to.equal(false);

    const pending = agentActions(
      makeAgent({
        control_state: 'install_pending',
      } as Partial<ManagedAgentSummary>),
      rowCtx
    );
    const talk = pending.find((action) => action.id === 'talk');
    expect(talk, 'a pending install still says Talk, disabled').to.exist;
    expect(talk!.disabled).to.equal(true);

    expect(
      actionIds(agentActions(makeAgent(), rowCtx)),
      'a runtime without Agent Control gets no Talk'
    ).to.not.contain('talk');
  });

  it('keeps Remove last, outlined and set apart (DESIGN.md)', () => {
    const actions = agentActions(makeAgent(), rowCtx);
    const decommission = actions.find(
      (action) => action.id === 'decommission'
    )!;
    expect(decommission.separated).to.equal(true);
    expect(decommission.variant).to.equal('danger');
    expect(decommission.outline).to.equal(true);
    const remove = actions[actions.length - 1];
    expect(remove.id).to.equal('remove');
    expect(remove.variant).to.equal('danger');
    expect(remove.outline).to.equal(true);
    expect(remove.separated).to.equal(true);
  });

  it('offers only what a surface wired handlers for', () => {
    expect(
      actionIds(agentActions(makeAgent(), { onLifecycle: () => {} }))
    ).to.deep.equal(['pause', 'decommission']);
  });

  it('offers a running and a stopped agent only their common actions', () => {
    const running = agentActions(makeAgent({ id: 'a' }), rowCtx);
    const stopped = agentActions(
      makeAgent({ id: 'b', lifecycle_state: 'suspended' }),
      rowCtx
    );
    expect(actionIds(intersectActions([running, stopped]))).to.deep.equal([
      'rename',
      'edit-tags',
      'decommission',
      'remove',
    ]);
  });

  it('leaves two running agents every lifecycle move they share', () => {
    const one = agentActions(makeAgent({ id: 'a' }), rowCtx);
    const two = agentActions(makeAgent({ id: 'b' }), rowCtx);
    expect(actionIds(intersectActions([one, two]))).to.contain('pause');
  });
});

package cmd

import (
	"io"
	"os"
